// Generated by /ship coverage audit
// Value: protects=the tab bar collapses on a downward run, expands on an upward run or near the top, and ignores end-of-list rubber-banding;
//   fails_when=a collapse/expand threshold, the near-top reset, run reset on a direction flip or the overscroll clamp (incl. bottom inset) changes;
//   why_new=the direction rules became a UI-thread worklet with overscroll clamping and no test drove them through the exported scroll hooks;
//   seam=none;
//   no_claim=green does not prove Reanimated runs these worklets on the UI thread or the bar animates.
import { beforeEach, describe, expect, mock, test } from "bun:test";
import { createElement, useMemo } from "react";
import { renderToStaticMarkup } from "react-dom/server";

type Box<T> = { value: T; get: () => T; set: (next: T) => void };

function box<T>(initial: T): Box<T> {
  const shared: Box<T> = {
    value: initial,
    get: () => shared.value,
    set: (next) => {
      shared.value = next;
    },
  };
  return shared;
}

// Reanimated's UI-thread runtime does not exist under bun. These fakes keep the hook plumbing but
// run the worklets inline: shared values are plain boxes, and the scroll hooks hand back the
// handlers they were given so the test can drive the real code with scroll events.
let nativeScrollHandler: ((event: { y: number; maxY: number }) => void) | undefined;

mock.module("react-native-reanimated", () => ({
  useSharedValue: <T>(initial: T) => useMemo(() => box(initial), []),
  useAnimatedScrollHandler: (handlers: unknown) => handlers,
  useHandler: () => ({ context: {}, doDependenciesDiffer: false }),
  useEvent: (handler: (event: { y: number; maxY: number }) => void) => {
    nativeScrollHandler = handler;
    return handler;
  },
}));

const minimize =
  await import("../../../../../../../apps/mobile/src/components/ui/tab-bar/hooks/use-minimize");
const {
  COLLAPSE_DISTANCE,
  EXPAND_DISTANCE,
  MIN_SCROLL_Y,
  TabBarMinimizeProvider,
  useOptionalTabBarMinimize,
  useTabBarMinimizeNativeScroll,
  useTabBarMinimizeScroll,
} = minimize;

type ScrollGeometry = { contentHeight?: number; layoutHeight?: number; insetBottom?: number };
type ScrollHandlers = {
  onScroll: (event: {
    contentOffset: { y: number };
    contentSize: { height: number };
    contentInset: { bottom: number };
    layoutMeasurement: { height: number };
  }) => void;
};
type ScrollYArg = Parameters<typeof useTabBarMinimizeScroll>[0];

// A tall list in a shorter viewport: the scrollable range ends at offset 9200.
const TALL: Required<ScrollGeometry> = { contentHeight: 10_000, layoutHeight: 800, insetBottom: 0 };

beforeEach(() => {
  nativeScrollHandler = undefined;
});

function mountScrollHook(options: { provider: boolean }) {
  const scrollY = box(0);
  let controls: ReturnType<typeof useOptionalTabBarMinimize>;
  let handlers: ScrollHandlers | undefined;

  function Probe() {
    controls = useOptionalTabBarMinimize();
    handlers = useTabBarMinimizeScroll(
      scrollY as unknown as ScrollYArg,
    ) as unknown as ScrollHandlers;
    return null;
  }

  renderToStaticMarkup(
    options.provider
      ? createElement(TabBarMinimizeProvider, null, createElement(Probe))
      : createElement(Probe),
  );

  return {
    scrollY,
    minimized: () => controls?.minimizedSV.get(),
    scroll(y: number, geometry: ScrollGeometry = {}) {
      const { contentHeight, layoutHeight, insetBottom } = { ...TALL, ...geometry };
      handlers?.onScroll({
        contentOffset: { y },
        contentSize: { height: contentHeight },
        contentInset: { bottom: insetBottom },
        layoutMeasurement: { height: layoutHeight },
      });
    },
  };
}

describe("useTabBarMinimizeScroll direction rules", () => {
  test("minimizes after a downward run of COLLAPSE_DISTANCE and not a point earlier", () => {
    const bar = mountScrollHook({ provider: true });

    bar.scroll(MIN_SCROLL_Y);
    expect(bar.minimized()).toBe(false);

    bar.scroll(MIN_SCROLL_Y + COLLAPSE_DISTANCE - 1);
    expect(bar.minimized()).toBe(false);

    bar.scroll(MIN_SCROLL_Y + COLLAPSE_DISTANCE);
    expect(bar.minimized()).toBe(true);
  });

  test("expands after an upward run of EXPAND_DISTANCE and not a point earlier", () => {
    const bar = mountScrollHook({ provider: true });
    const bottom = MIN_SCROLL_Y + 500;

    bar.scroll(bottom);
    expect(bar.minimized()).toBe(true);

    bar.scroll(bottom - (EXPAND_DISTANCE - 1));
    expect(bar.minimized()).toBe(true);

    bar.scroll(bottom - EXPAND_DISTANCE);
    expect(bar.minimized()).toBe(false);
  });

  test("restarts the accumulated run whenever the scroll direction flips", () => {
    const bar = mountScrollHook({ provider: true });
    const bottom = MIN_SCROLL_Y + 500;
    const almostCollapse = COLLAPSE_DISTANCE - 1;
    const almostExpand = EXPAND_DISTANCE - 1;

    bar.scroll(bottom);
    expect(bar.minimized()).toBe(true);

    // Almost a full downward run, then a short upward move: the downward run must not carry over
    // into the upward one, or its sum would reach EXPAND_DISTANCE and expand the bar early.
    bar.scroll(bottom + almostCollapse);
    bar.scroll(bottom + almostCollapse - almostExpand);
    expect(bar.minimized()).toBe(true);

    // One more point upward completes a fresh upward run and expands the bar.
    bar.scroll(bottom + almostCollapse - almostExpand - 1);
    expect(bar.minimized()).toBe(false);

    // The mirror case: a short upward run then an almost full downward run must not add up to a collapse.
    const top = bottom + almostCollapse - 2 * almostExpand - 1;
    bar.scroll(top);
    bar.scroll(top + almostCollapse);
    expect(bar.minimized()).toBe(false);
  });

  test("returns to expanded at MIN_SCROLL_Y even when the last upward run is shorter than EXPAND_DISTANCE", () => {
    const bar = mountScrollHook({ provider: true });

    bar.scroll(MIN_SCROLL_Y + 5);
    expect(bar.minimized()).toBe(true);

    // A short step that stays below the upward threshold and above the top keeps the bar minimized.
    bar.scroll(MIN_SCROLL_Y + 1);
    expect(bar.minimized()).toBe(true);

    bar.scroll(MIN_SCROLL_Y);
    expect(bar.minimized()).toBe(false);
  });
});

describe("useTabBarMinimizeScroll overscroll", () => {
  // Scrollable range ends at offset 200.
  const list = { contentHeight: 1000, layoutHeight: 800 };

  test("does not re-expand a minimized bar while the list bounces past its end", () => {
    const bar = mountScrollHook({ provider: true });

    bar.scroll(200, list);
    expect(bar.minimized()).toBe(true);

    for (const bounce of [240, 215, 200]) {
      bar.scroll(bounce, list);
      expect(bar.minimized()).toBe(true);
    }

    // A real upward scroll from the end still expands the bar.
    bar.scroll(190, list);
    expect(bar.minimized()).toBe(false);
  });

  test("counts the bottom content inset as scrollable range before clamping", () => {
    const bar = mountScrollHook({ provider: true });
    const inset = { ...list, insetBottom: 100 };

    bar.scroll(250, inset);
    expect(bar.minimized()).toBe(true);

    // Past the inset-extended end (300) the rest is rubber-banding.
    bar.scroll(340, inset);
    bar.scroll(310, inset);
    expect(bar.minimized()).toBe(true);

    // 250 is inside the inset-extended range, so moving up from it is a real scroll.
    const upward = mountScrollHook({ provider: true });
    upward.scroll(250, inset);
    upward.scroll(240, inset);
    expect(upward.minimized()).toBe(false);
  });

  test("reports the raw offset to the header while the direction rules see the clamped one", () => {
    const bar = mountScrollHook({ provider: true });

    bar.scroll(240, list);

    expect(bar.scrollY.get()).toBe(240);
  });

  test("never minimizes for content shorter than the viewport", () => {
    const bar = mountScrollHook({ provider: true });

    bar.scroll(100, { contentHeight: 500, layoutHeight: 800 });

    expect(bar.minimized()).toBe(false);
  });
});

describe("useTabBarMinimizeScroll outside a TabBarMinimizeProvider", () => {
  test("only keeps the header offset in sync and never throws", () => {
    const bar = mountScrollHook({ provider: false });

    expect(() => {
      bar.scroll(300);
      bar.scroll(100);
    }).not.toThrow();
    expect(bar.minimized()).toBeUndefined();
    expect(bar.scrollY.get()).toBe(100);
  });
});

describe("useTabBarMinimizeNativeScroll", () => {
  function mountNativeHook(options: { offset?: number; onScroll?: (y: number) => void }) {
    const scrollY = box(0);
    let controls: ReturnType<typeof useOptionalTabBarMinimize>;

    function Probe() {
      controls = useOptionalTabBarMinimize();
      useTabBarMinimizeNativeScroll(scrollY as unknown as ScrollYArg, options);
      return null;
    }

    renderToStaticMarkup(createElement(TabBarMinimizeProvider, null, createElement(Probe)));

    return {
      scrollY,
      minimized: () => controls?.minimizedSV.get(),
      scroll: (y: number, maxY: number) => nativeScrollHandler?.({ y, maxY }),
    };
  }

  test("applies the offset to the header value, the callback and the direction rules", () => {
    const seen: number[] = [];
    const list = mountNativeHook({ offset: 100, onScroll: (y) => seen.push(y) });

    // A list resting under a 100pt top inset reports -100 natively: that is offset 0 here.
    list.scroll(-100, 1000);
    expect(list.scrollY.get()).toBe(0);
    expect(list.minimized()).toBe(false);

    list.scroll(-100 + MIN_SCROLL_Y + COLLAPSE_DISTANCE, 1000);
    expect(list.minimized()).toBe(true);
    expect(seen).toEqual([0, MIN_SCROLL_Y + COLLAPSE_DISTANCE]);
  });

  test("clamps overscroll against the offset-shifted end without altering the reported offset", () => {
    const seen: number[] = [];
    const list = mountNativeHook({ offset: 100, onScroll: (y) => seen.push(y) });

    list.scroll(400, 400);
    expect(list.minimized()).toBe(true);

    list.scroll(430, 400);
    list.scroll(410, 400);
    expect(list.minimized()).toBe(true);
    expect(list.scrollY.get()).toBe(510);
    expect(seen).toEqual([500, 530, 510]);

    list.scroll(390, 400);
    expect(list.minimized()).toBe(false);
  });
});
